import { concatMap, forkJoin, map, of, type Observable } from "rxjs";

import { multisetDiff } from "../runtime/diff.ts";
import { selectRows } from "../runtime/rows.ts";
import type {
  IArrivalBatch,
  IArrivalRow,
  IGenProgram,
  IRow,
  IRowValue,
  ISqlSeam,
  ITickDeltas,
  SqlStatement,
} from "../runtime/types.ts";

interface IBootStatement {
  sql: string;
  params: readonly (string | number)[];
}

type IGenProgramWithBoot = IGenProgram & { readonly boot: readonly IBootStatement[] };

function bindArgs(values: readonly IRowValue[]): (string | number | bigint)[] {
  return values.map((value) => (typeof value === "number" && Number.isInteger(value) ? BigInt(value) : value));
}

const ddl: readonly string[] = [
  `CREATE TABLE "stream_end" ("args" TEXT NOT NULL, "col2" TEXT NOT NULL)`,
  `CREATE TABLE "stream_item" ("args" TEXT NOT NULL, "col2" INTEGER NOT NULL, "col3" TEXT NOT NULL)`,
  `CREATE TABLE "stream_status" ("args" TEXT NOT NULL, "col2" TEXT NOT NULL, PRIMARY KEY ("args", "col2")) WITHOUT ROWID`,
];

const relColumns: Record<string, readonly string[]> = {
  stream_end: ["args", "col2"],
  stream_item: ["args", "col2", "col3"],
  stream_status: ["args", "col2"],
};

const arrivalTargets: readonly string[] = ["stream_end", "stream_item"];

const boot: readonly IBootStatement[] = [
  { sql: `DELETE FROM "stream_status"`, params: [] },
  { sql: `INSERT OR IGNORE INTO "stream_status" ("args", "col2") SELECT b0."args", 'running' FROM "stream_item" b0 WHERE NOT EXISTS (SELECT 1 FROM "stream_end" n0 WHERE n0."args" = b0."args")`, params: [] },
  { sql: `INSERT OR IGNORE INTO "stream_status" ("args", "col2") SELECT b0."args", 'done' FROM "stream_end" b0`, params: [] },
];

type Snapshot = {
  readonly stream_end: readonly IRow[];
  readonly stream_item: readonly IRow[];
  readonly stream_status: readonly IRow[];
};

function readSnapshot(seam: ISqlSeam): Observable<Snapshot> {
  return forkJoin({
    stream_end: selectRows(seam, `SELECT CASE WHEN json_valid("args") AND json_type("args") = 'object' THEN json_extract("args", '$.fn') || '(' || (SELECT group_concat(value, ',') FROM json_each("args", '$.args')) || ')' ELSE "args" END AS "args", CASE WHEN json_valid("col2") AND json_type("col2") = 'object' THEN json_extract("col2", '$.fn') || '(' || (SELECT group_concat(value, ',') FROM json_each("col2", '$.args')) || ')' ELSE "col2" END AS "col2" FROM "stream_end"`, relColumns.stream_end!),
    stream_item: selectRows(seam, `SELECT CASE WHEN json_valid("args") AND json_type("args") = 'object' THEN json_extract("args", '$.fn') || '(' || (SELECT group_concat(value, ',') FROM json_each("args", '$.args')) || ')' ELSE "args" END AS "args", CASE WHEN json_valid("col2") AND json_type("col2") = 'object' THEN json_extract("col2", '$.fn') || '(' || (SELECT group_concat(value, ',') FROM json_each("col2", '$.args')) || ')' ELSE "col2" END AS "col2", CASE WHEN json_valid("col3") AND json_type("col3") = 'object' THEN json_extract("col3", '$.fn') || '(' || (SELECT group_concat(value, ',') FROM json_each("col3", '$.args')) || ')' ELSE "col3" END AS "col3" FROM "stream_item"`, relColumns.stream_item!),
    stream_status: selectRows(seam, `SELECT CASE WHEN json_valid("args") AND json_type("args") = 'object' THEN json_extract("args", '$.fn') || '(' || (SELECT group_concat(value, ',') FROM json_each("args", '$.args')) || ')' ELSE "args" END AS "args", CASE WHEN json_valid("col2") AND json_type("col2") = 'object' THEN json_extract("col2", '$.fn') || '(' || (SELECT group_concat(value, ',') FROM json_each("col2", '$.args')) || ')' ELSE "col2" END AS "col2" FROM "stream_status"`, relColumns.stream_status!),
  });
}

const ARRIVAL_STATEMENTS: Record<string, { kind: "log" | "set"; addSql: string; delSql: string | null }> = {
  stream_end: { kind: "log", addSql: `INSERT INTO "stream_end" ("args", "col2") VALUES (?, ?)`, delSql: null },
  stream_item: { kind: "log", addSql: `INSERT INTO "stream_item" ("args", "col2", "col3") VALUES (?, ?, ?)`, delSql: null },
};

function arrivalStatement(arrival: IArrivalRow): SqlStatement {
  const template = ARRIVAL_STATEMENTS[arrival.rel];
  if (template === undefined) {
    throw new Error(`terminal_is_terminal: tick received an arrival for undeclared rel '${arrival.rel}'`);
  }
  if (arrival.sign === "del") {
    if (template.kind === "log") {
      throw new Error(`terminal_is_terminal: retract from log rel '${arrival.rel}' (engine.pl retract_from_log)`);
    }
    if (template.delSql === null) {
      throw new Error(`terminal_is_terminal: rel '${arrival.rel}' has no delete statement`);
    }
    return { sql: template.delSql, args: bindArgs(arrival.row) };
  }
  return { sql: template.addSql, args: bindArgs(arrival.row) };
}

function applyArrivals(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<unknown> {
  const statements: SqlStatement[] = arrivals.map(arrivalStatement);
  return seam.runner.batch(seam.db, statements);
}

function recomputeLevels(seam: ISqlSeam): Observable<void> {
  const sql = `DELETE FROM "stream_status";\nINSERT OR IGNORE INTO "stream_status" ("args", "col2") SELECT b0."args", 'running' FROM "stream_item" b0 WHERE NOT EXISTS (SELECT 1 FROM "stream_end" n0 WHERE n0."args" = b0."args");\nINSERT OR IGNORE INTO "stream_status" ("args", "col2") SELECT b0."args", 'done' FROM "stream_end" b0`;
  return seam.runner.executeMultiple(seam.db, sql);
}

function buildDeltas(before: Snapshot, after: Snapshot): ITickDeltas {
  const stream_end = multisetDiff(before.stream_end, after.stream_end);
  const stream_item = multisetDiff(before.stream_item, after.stream_item);
  const stream_status = multisetDiff(before.stream_status, after.stream_status);
  return {
    rels: [
      { rel: "stream_end", add: stream_end.add, del: stream_end.del },
      { rel: "stream_item", add: stream_item.add, del: stream_item.del },
      { rel: "stream_status", add: stream_status.add, del: stream_status.del },
    ],
    carryPending: false,
  };
}

function runTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  return readSnapshot(seam).pipe(
    concatMap((before) => applyArrivals(seam, arrivals).pipe(map(() => before))),
    concatMap((before) => recomputeLevels(seam).pipe(map(() => before))),
    concatMap((before) => readSnapshot(seam).pipe(map((after) => buildDeltas(before, after)))),
  );
  // terminal_is_terminal: no edge rules -- absorb arrivals, recompute levels, diff.
}

export const program: IGenProgramWithBoot = {
  name: "terminal_is_terminal",
  ddl,
  relColumns,
  arrivalTargets,
  boot,
  tick: runTick,
};
